import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"L1 extension guide - overview","description":"","frontmatter":{},"headers":[],"relativePath":"l1/overview.md","filePath":"l1/overview.md"}'),d={name:"l1/overview.md"};function l(s,e,i,n,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="l1-extension-guide-overview" tabindex="-1">L1 extension guide - overview <a class="header-anchor" href="#l1-extension-guide-overview" aria-label="Permalink to &quot;L1 extension guide - overview&quot;">​</a></h1><p>L0 ships without any L1. The whole point of the architecture is the surface L0 exposes so L1 <em>can</em> exist: 162 numbered extension interfaces plus the driver / OTA / watchdog / health / klog header families, and a shared-object loader so modules can arrive at runtime.</p><h2 id="the-layers-once-more" tabindex="-1">The layers, once more <a class="header-anchor" href="#the-layers-once-more" aria-label="Permalink to &quot;The layers, once more&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1  your module: .so loaded by the in-tree ld.so, or a built-in</span></span>
<span class="line"><span>    compiled against the surface headers</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>    162 numbered interfaces + driver/OTA/watchdog/health/klog</span></span>
<span class="line"><span>    families (INTERFACES.md = the full generated tables)</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>L0  Open Cube OS kernel + oc&gt; shell (this repo)</span></span></code></pre></div><h2 id="where-the-surface-lives" tabindex="-1">Where the surface lives <a class="header-anchor" href="#where-the-surface-lives" aria-label="Permalink to &quot;Where the surface lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>What it covers</th></tr></thead><tbody><tr><td><code>l1/l1_ext.h</code></td><td>fb info, font engines, console hook, config read/write, update chain, power, shell bridge, self-test</td></tr><tr><td><code>l1/l1_wp8a.h</code></td><td>process/fd/signal/mmap/chdir - the Unix-shaped user API</td></tr><tr><td><code>l1/l1_wp8b.h</code></td><td>the dynamic loader (elf_load_dynamic, so_load, dlsym_impl, reloc_apply...)</td></tr><tr><td><code>l1/l1_wp8cd.h</code></td><td>shell built-ins, tool embedding, jobs</td></tr><tr><td><code>tui/tui_ext.h</code></td><td>37 TUI declarations (windows/menus/forms/panels/text)</td></tr><tr><td><code>drivers/block/driver_block_blk.h</code></td><td>block registration + I/O</td></tr><tr><td><code>drivers/nic/driver_nic.h</code></td><td>NIC registration + I/O</td></tr><tr><td><code>drivers/snd/driver_snd.h</code></td><td>sound registration + playback</td></tr><tr><td><code>kernel/ota/ota_ab.h</code>, <code>ota_update.h</code></td><td>slots + the update chain</td></tr><tr><td><code>kernel/core/core_watchdog.h</code>, <code>core_health.h</code></td><td>watchdog slots + health metrics</td></tr><tr><td><code>kernel/lib/lib_klog.h</code></td><td>the kernel log</td></tr></tbody></table><p>The complete declaration tables (file, line, signature for all 278 declarations) are generated into <a href="./../root/INTERFACES.html">INTERFACES.md</a> by <code>make api-docs</code>.</p><h2 id="the-count-that-matters" tabindex="-1">The count that matters <a class="header-anchor" href="#the-count-that-matters" aria-label="Permalink to &quot;The count that matters&quot;">​</a></h2><ul><li><strong>162 numbered L1 interfaces</strong> - the README formula 57+8+13+7+26+11+7+9+8+16, the repo-wide consistency number.</li><li>278 total callable declarations across the 13 surface headers (includes internal helpers and documented unnumbered groups).</li></ul><h2 id="how-modules-load" tabindex="-1">How modules load <a class="header-anchor" href="#how-modules-load" aria-label="Permalink to &quot;How modules load&quot;">​</a></h2><p>Three paths, all real:</p><ol><li><strong>Compiled-in L1</strong> - your module compiles into the kernel and calls the surface directly (how the TUI command bridge works).</li><li><strong>Shared object at runtime</strong> - <code>libs/ld_so.c</code> loads an ELF .so, resolves symbols, applies relocations: <a href="./solib-loader.html">solib-loader.md</a>.</li><li><strong>Embedded tools</strong> - <code>tool_register</code> embeds an ELF payload the shell can <code>run</code>.</li></ol><h2 id="walk-through-order" tabindex="-1">Walk-through order <a class="header-anchor" href="#walk-through-order" aria-label="Permalink to &quot;Walk-through order&quot;">​</a></h2><ol><li>This page.</li><li><a href="./surface-map.html">surface-map.md</a> - the 162 by functional group.</li><li>The family pages: <a href="./driver-block.html">driver-block.md</a>, <a href="./driver-nic.html">driver-nic.md</a>, <a href="./driver-snd.html">driver-snd.md</a>, <a href="./ota.html">ota.md</a>, <a href="./watchdog-health.html">watchdog-health.md</a>, <a href="./shell-bridge.html">shell-bridge.md</a>.</li><li><a href="./tui-ext.html">tui-ext.md</a> - building UI from L1.</li><li><a href="./writing-modules.html">writing-modules.md</a> - a complete module, from source to <code>run</code>.</li></ol>`,14)])])}const p=t(d,[["render",l]]);export{u as __pageData,p as default};
